def backfill_rejection_origin(apps, schema_editor):
    """Los rechazos del validador vuelven a quedar como decisión en terreno.

    La migración 0008 les puso ``validacion_terreno`` a los rechazos que
    existían, pero la transición ``rechazar`` seguía declarada con el origen
    por defecto, así que cada rechazo posterior quedó como ``manual`` y el panel
    —que reconoce al validador por el origen— dejó de mostrarlo como decisión
    suya. Un rechazo es el único asiento que sale de *Pendiente de validación* a
    *Cancelado* con un responsable: nada más lo pudo producir hasta acá.
    """
    History = apps.get_model("reports", "ReportStatusHistory")
    History.objects.filter(
        previous_status="pendiente_validacion",
        status="cancelado",
        changed_by__isnull=False,
        origin="manual",
    ).update(origin="validacion_terreno")


